<section class="panel"><div class="panel-header"><div><h2>Contas de acesso</h2><p><?= count($usuarios) ?> usuário(s) encontrado(s).</p></div><a class="btn btn-primary" href="index.php?entidade=usuarios&acao=novo">+ Novo usuário</a></div>
<form class="filters" method="get"><input type="hidden" name="entidade" value="usuarios"><div class="field grow"><label for="buscar">Pesquisar</label><input id="buscar" name="buscar" value="<?= e($busca) ?>" placeholder="Nome ou e-mail"></div><div class="field"><label for="nivel">Perfil</label><select id="nivel" name="nivel"><option value="">Todos</option><?php foreach (['admin'=>'Administrador','operador'=>'Operador','cliente'=>'Cliente'] as $key=>$label): ?><option value="<?= $key ?>" <?= $nivel===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></div><button class="btn btn-secondary">Filtrar</button></form>
<div class="table-wrap"><table><thead><tr><th>ID</th><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Cadastro</th><th>Ações</th></tr></thead><tbody><?php foreach ($usuarios as $u): ?><tr><td><?= (int)$u['id'] ?></td><td class="text-left"><?= e($u['nome']) ?></td><td><?= e($u['email']) ?></td><td><?= e(['admin'=>'Administrador','operador'=>'Operador','cliente'=>'Cliente'][$u['nivel']]??$u['nivel']) ?></td><td><?= e(date('d/m/Y',strtotime($u['created_at']))) ?></td><td><div class="row-actions"><a class="icon-btn" href="index.php?entidade=usuarios&acao=editar&id=<?= (int)$u['id'] ?>">✏️</a><?php if ((int)$u['id']!==(int)$_SESSION['usuario_id']): ?><form method="post" action="index.php?entidade=usuarios&acao=excluir" class="inline-form" onsubmit="return confirm('Excluir este usuário?')"><input type="hidden" name="csrf_token" value="<?= e(csrfToken()) ?>"><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><button class="icon-btn danger">🗑️</button></form><?php else: ?><small>Conta atual</small><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div></section>
